package com.tihai.controller;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import org.springframework.test.util.ReflectionTestUtils;import java.util.*;import java.util.concurrent.*;import java.nio.file.*;import java.io.*;import com.tihai.utils.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class ExamAutomationTest {
 @TempDir Path temp;
 static String html(int i){String type=i==0?"0":i==1?"1":"3";String labels=i==2?"true":"A";return "<input id=courseId value=10><input id=classId value=20><input id=testPaperId value=30><input id=start value="+i+"><ul><li onclick=\"getTheQuestionByStart(0, '0')\">1</li><li onclick=\"getTheQuestionByStart(1, '0')\">2</li><li onclick=\"getTheQuestionByStart(2, '0')\">3</li></ul><div class=singleQuesId data="+(91+i)+"><h3 class=mark_name>Question "+i+"</h3><form id=submitTest><input name=type"+(91+i)+" value="+type+"><div class=stem_answer><div class=answerBg><span class=num_option data="+labels+">A</span><div class=answer_p>Alpha</div></div><div class=answerBg><span class=num_option_dx data=B>B</span><div class=answer_p>Beta</div></div></div></form></div>";}
 class Bridge implements ExamBrowserSession {BlockingQueue<Map<String,Object>> events=new LinkedBlockingQueue<>();int page,applied,submitted;boolean hold,uncertain,change,closed;
  void emit(String event,String key,Object value){Map<String,Object> e=new HashMap<>();e.put("event",event);if(key!=null)e.put(key,value);events.add(e);}
  public void send(Map<String,Object> c){String op=(String)c.get("op");if("init".equals(op)){if(hold)emit("verification","message","请完成安全验证");else emit("paper","html",html(0));}if("apply".equals(op)){applied++;emit("applied","id",c.get("id"));}if("next".equals(op)){page++;emit("paper","html",change?html(page).replace("id=courseId value=10","id=courseId value=999"):html(page));}if("submit".equals(op)){submitted++;emit("submit_sent",null,null);emit(uncertain?"uncertain":"completed","message",uncertain?"平台结果待确认":"平台已交卷");}}
  public Map<String,Object> read()throws IOException{try{return events.take();}catch(InterruptedException e){throw new IOException("interrupted");}}
  public void close(){closed=true;}
 }
 class Fixture extends ExamController implements AutoCloseable {Bridge bridge=new Bridge();CourseExamCatalog fakeCatalog=mock(CourseExamCatalog.class);Query fakeQuery=mock(Query.class);SecurityAlertHub alerts=new SecurityAlertHub();ExamStateStore fakeStore=new ExamStateStore(temp);
  Fixture()throws Exception{CourseExamCatalog.Entry e=new CourseExamCatalog.Entry();e.id="fixture";e.account="fixture-account";e.courseId="10";e.clazzId="20";e.examId="30";e.title="Fixture exam";e.courseTitle="Fixture course";e.actionable=true;when(fakeCatalog.entry("fixture")).thenReturn(e);when(fakeQuery.queryAnswerSync(any())).thenReturn("Beta","Alpha#Beta","正确");ReflectionTestUtils.setField(this,"catalog",fakeCatalog);ReflectionTestUtils.setField(this,"query",fakeQuery);ReflectionTestUtils.setField(this,"progress",new LiveProgressTracker());ReflectionTestUtils.setField(this,"vision",mock(QuizVisionService.class));ReflectionTestUtils.setField(this,"store",fakeStore);ReflectionTestUtils.setField(this,"security",alerts);}
  @Override protected ExamBrowserSession openBrowser(String id){return bridge;}@Override protected Map<String,Object> init(Job j){return Collections.singletonMap("op","init");}
  void begin(boolean auto){Map<String,Object> b=new HashMap<>();b.put("id","fixture");b.put("confirmed",true);b.put("autoSubmit",auto);assertEquals(200,start(b).get("code"));}
  Map<String,Object> waitState(String expected)throws Exception{long end=System.currentTimeMillis()+5000;while(System.currentTimeMillis()<end){Map<String,Object> state=(Map<String,Object>)draft(Collections.singletonMap("id","fixture")).get("data");if(state!=null&&expected.equals(state.get("state")))return state;Thread.sleep(10);}throw new AssertionError(expected);}
  public void close(){shutdown();}
 }
 @Test void autoAnswersAllThreeTypesAndSubmitsExactlyOnce()throws Exception{try(Fixture f=new Fixture()){assertNotEquals(200,f.start(Collections.singletonMap("id","fixture")).get("code"));f.begin(true);Map<String,Object> result=f.waitState("completed");assertEquals(3,result.get("done"));assertEquals(3,f.bridge.applied);assertEquals(1,f.bridge.submitted);assertNotEquals(200,f.submit(new HashMap<String,Object>(){{put("id","fixture");put("confirmed",true);}}).get("code"));}}
 @Test void manualModeWaitsForExplicitSubmit()throws Exception{try(Fixture f=new Fixture()){f.begin(false);f.waitState("ready");assertEquals(0,f.bridge.submitted);Map<String,Object> body=new HashMap<>();body.put("id","fixture");assertNotEquals(200,f.submit(body).get("code"));body.put("confirmed",true);assertEquals(200,f.submit(body).get("code"));f.waitState("completed");assertEquals(1,f.bridge.submitted);}}
 @Test void verificationRaisesAlertThenResolvesAfterNormalPaperArrives()throws Exception{try(Fixture f=new Fixture()){f.bridge.hold=true;f.begin(true);f.waitState("verification");assertEquals(1,f.alerts.snapshot().size());assertEquals(0,f.bridge.applied);f.bridge.emit("paper","html",html(0));f.waitState("completed");assertTrue(f.alerts.snapshot().isEmpty());}}
 @Test void foreignExamPageStopsWithoutSubmitting()throws Exception{try(Fixture f=new Fixture()){f.bridge.change=true;f.begin(true);f.waitState("failed");assertEquals(1,f.bridge.applied);assertEquals(0,f.bridge.submitted);}}
 @Test void unknownResultPersistsAndCannotResubmitAfterRestart()throws Exception{try(Fixture f=new Fixture()){f.bridge.uncertain=true;f.begin(true);f.waitState("uncertain");assertTrue(ExamStateStore.mayHaveSubmitted(new ExamStateStore(temp).load("fixture")));assertNotEquals(200,f.start(new HashMap<String,Object>(){{put("id","fixture");put("confirmed",true);put("autoSubmit",true);}}).get("code"));assertEquals(1,f.bridge.submitted);}}
 @Test void stopWhileVerificationPreventsAnsweringOrSubmitting()throws Exception{try(Fixture f=new Fixture()){f.bridge.hold=true;f.begin(true);f.waitState("verification");assertEquals(200,f.stop(Collections.singletonMap("id","fixture")).get("code"));f.waitState("stopped");assertEquals(0,f.bridge.applied);assertEquals(0,f.bridge.submitted);}}
}
